extends SceneTree
## Temporary headless smoke test: AI movement, player hand-over, jump.

var elapsed := 0.0
var char_node: Node
var last_pos := Vector3.ZERO
var ai_moved := 0.0
var player_moved := 0.0
var jumped := false
var phase := 0  # 0 = AI, 1 = player hold W


func _initialize() -> void:
	print("actions: move_forward=", InputMap.action_get_events("move_forward").size(),
		" jump=", InputMap.action_get_events("jump").size(),
		" interact=", InputMap.action_get_events("interact").size())
	var s: Node = load("res://scenes/main.tscn").instantiate()
	root.add_child(s)


func _physics_process(delta: float) -> void:
	elapsed += delta
	if char_node == null:
		char_node = _find_character(root)
		if char_node:
			last_pos = char_node.global_position
			print("found character: ", char_node.name)

	if char_node:
		var p: Vector3 = char_node.global_position
		if phase == 0:
			ai_moved += p.distance_to(last_pos)
			if elapsed > 3.0:
				phase = 1
				var ev := InputEventKey.new()
				ev.physical_keycode = 87  # W
				ev.pressed = true
				Input.parse_input_event(ev)
		else:
			player_moved += p.distance_to(last_pos)
			if elapsed > 4.0 and not jumped:
				jumped = true
				var jev := InputEventKey.new()
				jev.physical_keycode = 32  # Space
				jev.pressed = true
				char_node._unhandled_input(jev)
			if elapsed > 4.3 and p.y > 0.2:
				print("jump ok: y=", p.y)
		last_pos = p
		if fmod(elapsed, 1.0) < delta:
			print("t=%.1f pos=%s floor=%s phase=%d" % [elapsed, str(p), str(char_node.is_on_floor()), phase])

	if elapsed > 6.0:
		print("RESULT ai_moved=%.2f player_moved=%.2f" % [ai_moved, player_moved])
		var ok := ai_moved > 2.0 and player_moved > 0.5
		print("TEST ", "PASS" if ok else "FAIL")
		quit(0 if ok else 1)


func _find_character(n: Node) -> Node:
	if n is CharacterBody3D:
		return n
	for c in n.get_children():
		var r := _find_character(c)
		if r:
			return r
	return null

